564	
565	    const { libraryItemIds } = req.body
566	    if (!libraryItemIds?.length || !Array.isArray(libraryItemIds)) {
567	      return res.status(400).send('Invalid request body')
568	    }
569	
570	    const itemsToDelete = await Database.libraryItemModel.findAllExpandedWhere({
571	      id: libraryItemIds
572	    })
573	
574	    if (!itemsToDelete.length) {
575	      return res.sendStatus(404)
576	    }
577	
578	    // Ensure user has permission to delete these library items
579	    if (!ensureUserCanAccessLibraryItemsForBatch(req, res, itemsToDelete)) {
580	      return
581	    }
582	
583	    const libraryId = itemsToDelete[0].libraryId
584	
585	    for (const libraryItem of itemsToDelete) {
586	      const libraryItemPath = libraryItem.path
587	      Logger.info(`[LibraryItemController] (${hardDelete ? 'Hard' : 'Soft'}) deleting Library Item "${libraryItem.media.title}" with id "${libraryItem.id}"`)
588	      const mediaItemIds = []
589	      const seriesIds = []
590	      const authorIds = []
591	      if (libraryItem.isPodcast) {
592	        mediaItemIds.push(...libraryItem.media.podcastEpisodes.map((ep) => ep.id))
593	      } else {
594	        mediaItemIds.push(libraryItem.media.id)
595	        if (libraryItem.media.series?.length) {
596	          seriesIds.push(...libraryItem.media.series.map((se) => se.id))
597	        }
598	        if (libraryItem.media.authors?.length) {
599	          authorIds.push(...libraryItem.media.authors.map((au) => au.id))
600	        }
601	      }
602	      await this.handleDeleteLibraryItem(libraryItem.id, mediaItemIds, libraryItem.libraryId)
