// Transpiles original .js and converted .ts WITH comments and reports which JSDoc blocks (/** ... */) of the original are missing in the converted output.
const path = require('path'); const fs = require('fs'); const cp = require('child_process')
const repo = process.argv[2]; const name = process.argv[3]
const ts = require(path.join(repo, 'node_modules', 'typescript'))
const opts = { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS, esModuleInterop: true, strict: true, removeComments: false, allowJs: true, newLine: ts.NewLineKind.LineFeed }
const orig = cp.execSync(`git show HEAD:server/controllers/${name}.js`, { cwd: repo, encoding: 'utf8', maxBuffer: 1 << 26 })
const conv = fs.readFileSync(path.join(repo, 'server', 'controllers', name + '.ts'), 'utf8')
const a = ts.transpileModule(orig, { fileName: name + '.js', compilerOptions: opts }).outputText
const b = ts.transpileModule(conv, { fileName: name + '.ts', compilerOptions: opts }).outputText
const norm = (s) => s.replace(/\s+/g, ' ').trim()
const blocks = (s) => (s.match(/\/\*\*[\s\S]*?\*\//g) || []).map(norm)
const lineComments = (s) => (s.match(/^\s*\/\/.*$/gm) || []).map(norm)
const A = blocks(a), B = blocks(b)
const missing = A.filter((x) => !B.includes(x))
const extra = B.filter((x) => !A.includes(x))
console.log(name, 'JSDoc blocks orig', A.length, 'conv', B.length, 'missing', missing.length, 'extra', extra.length)
missing.forEach((m) => console.log('  MISSING:', m.slice(0, 160)))
extra.forEach((m) => console.log('  EXTRA:', m.slice(0, 160)))
const LA = lineComments(a), LB = lineComments(b)
const lm = LA.filter((x) => !LB.includes(x))
console.log('  own-line // comments orig', LA.length, 'conv', LB.length, 'missing', lm.length)
lm.forEach((m) => console.log('  MISSING LINE COMMENT:', m.slice(0, 160)))
// source-level check: every JSDoc block of the original source is still in the converted source, byte for byte
const srcBlocks = (s) => s.match(/\/\*\*[\s\S]*?\*\//g) || []
const sm = srcBlocks(orig).filter((x) => !conv.includes(x))
console.log('  source JSDoc blocks of the original not found unchanged in the .ts:', sm.length)
EOF
cd /d/SEM-2/574/Project/audiobookshelf-po && node "$A/emitcmt.js" "D:/SEM-2/574/Project/audiobookshelf-po" PodcastController && node "$A/emitcmt.js" "D:/SEM-2/574/Project/audiobookshelf-po" LibraryItemController; date +%T

